begin;
create function pg_temp.check_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'Assertion failed: %',message;end if;end$$;
select pg_temp.check_true(not has_function_privilege('anon','public.suite_brand_request(uuid,jsonb)','execute'),'anonymous brand write denied');
select pg_temp.check_true(not has_function_privilege('authenticated','private.editorial_snapshot(uuid)','execute'),'personal snapshots private');
select pg_temp.check_true(not has_table_privilege('anon','public.social_brand_settings','update'),'public brand is read only');
set local role anon;
select pg_temp.check_true((select theme_key='football' from public.social_brand_settings),'default theme publicly readable');
reset role;
set local role service_role;
select pg_temp.check_true((public.suite_brand_request('00000000-0000-4000-8000-000000000099',jsonb_build_object('colorScheme',(select color_scheme from public.social_brand_settings),'themeKey','easter'))->>'status')='403','unknown user denied');
select pg_temp.check_true((public.suite_brand_request('00000000-0000-4000-8000-000000000020',jsonb_build_object('colorScheme',(select color_scheme from public.social_brand_settings),'themeKey','<script>'))->>'status')='400','unknown theme rejected');
select pg_temp.check_true((public.suite_brand_request('00000000-0000-4000-8000-000000000020','{"colorScheme":12,"themeKey":"christmas"}')->>'status')='400','scalar colors rejected');
select pg_temp.check_true((select theme_key='football' from public.social_brand_settings),'invalid save has no effects');
select public.suite_brand_request('00000000-0000-4000-8000-000000000020',jsonb_build_object('colorScheme',(select color_scheme||'{"secret":"discarded"}'::jsonb from public.social_brand_settings),'themeKey','christmas'));
select pg_temp.check_true((select theme_key='christmas' and not(color_scheme ? 'secret') from public.social_brand_settings),'valid theme saved with seven public colors only');
select public.suite_brand_request('00000000-0000-4000-8000-000000000020',jsonb_build_object('colorScheme',(select color_scheme from public.social_brand_settings)));
select pg_temp.check_true((select theme_key='christmas' from public.social_brand_settings),'older color-only clients preserve theme');
insert into public.editorial_issues(id,title,kind,publishes_on,cover_path) values('00000000-0000-4000-8000-000000000050','Design test','stadium','2026-12-01','test-cover');
insert into public.editorial_articles(issue_id,title,body,kind,status) values('00000000-0000-4000-8000-000000000050','Grußwort','Guten Tag','free','ready');
update public.editorial_issues set brand_settings=(select jsonb_build_object('color_scheme',color_scheme,'theme_key',theme_key) from public.social_brand_settings) where id='00000000-0000-4000-8000-000000000050';
select pg_temp.check_true((public.preview_editorial_issue(id,version)#>>'{brand,theme_key}')='christmas','preview includes saved design') from public.editorial_issues where id='00000000-0000-4000-8000-000000000050';
select public.publish_editorial_issue(id,version,'00000000-0000-4000-8000-000000000020') from public.editorial_issues where id='00000000-0000-4000-8000-000000000050';
select public.suite_brand_request('00000000-0000-4000-8000-000000000020',jsonb_build_object('colorScheme',(select color_scheme||'{"panel":"#112233"}'::jsonb from public.social_brand_settings),'themeKey','summer'));
select pg_temp.check_true((select snapshot#>>'{brand,theme_key}'='christmas' and snapshot#>>'{brand,color_scheme,panel}'<>'#112233' from public.editorial_publications where issue_id='00000000-0000-4000-8000-000000000050'),'published colors and theme stay frozen');
update public.editorial_issues set brand_settings=(select jsonb_build_object('color_scheme',color_scheme,'theme_key',theme_key) from public.social_brand_settings) where id='00000000-0000-4000-8000-000000000050';
select pg_temp.check_true((select previewed_version<>version from public.editorial_issues where id='00000000-0000-4000-8000-000000000050'),'new design needs a new preview');
reset role;
rollback;
